import{_ as l,c as i,o as a,ah as e}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"《说卦传》简介","description":"易传 - 《说卦传》简介","frontmatter":{"title":"《说卦传》简介","description":"易传 - 《说卦传》简介"},"headers":[],"relativePath":"zh/classics/yizhuan/004.md","filePath":"zh/classics/yizhuan/004.md"}'),t={name:"zh/classics/yizhuan/004.md"};function s(r,p,n,c,_,o){return a(),i("div",null,[...p[0]||(p[0]=[e('<h1 id="《说卦传》简介" tabindex="-1">《说卦传》简介 <a class="header-anchor" href="#《说卦传》简介" aria-label="Permalink to “《说卦传》简介”">​</a></h1><p>《说卦传》主要解说八卦所象征的各类事物，阐述六十四卦的排列原理和各卦的属性意义。其功能作用在于辅助占断吉凶，揭示自然现象和社会现象的变化与相互关系，其要点在于触类旁通，对于理解爻辞中所出现的各类人事物有着重要参考意义。</p><p>说卦传</p><p>昔者圣人之作《易》也，幽赞于神明而生蓍，参天两地而倚数，观变于阴阳而立卦，发挥于刚柔而生爻，和顺于道德而理于义，穷理尽性以至于命。</p><p>昔者圣人之作《易》也，将以顺性命之理。是以立天之道曰阴与阳，立地之道曰柔与刚，立人之道曰仁与义。兼三才而两之，故《易》六画而成卦。分阴分阳，迭用柔刚，故《易》六位而成章。</p><p>天地定位，山泽通气，雷风相薄，水火不相射，八卦相错。数往者顺，知来者逆，是故《易》逆数也。</p><p>雷以动之，风以散之，雨以润之，日以烜之，艮以止之，兑以说之，乾以君之，坤以藏之。</p><p>帝出乎震，齐乎巽，相见乎离，致役乎坤，说言乎兑，战乎乾，劳乎坎，成言乎艮。万物出乎震，震东方也。齐乎巽，巽东南也；齐也者，言万物之絜齐也。</p><p>离也者，明也，万物皆相见，南方之卦也，圣人南面而听天下，向明而治，盖取诸此也。坤也者，地也，万物皆致养焉，故曰：致役乎坤。兑，正秋也，万物之所说也，故曰：说言乎兑。战乎乾，乾西北之卦也，言阴阳相薄也。坎者水也，正北方之卦也，劳卦也，万物之所归也，故曰：劳乎坎。艮，东北之卦也。万物之所成终而成始也，故曰：成言乎艮。</p><p>神也者，妙万物而为言者也。动万物者莫疾乎雷，挠万物者莫疾乎风，躁万物者莫&amp;乎火，说万物者莫说乎泽，润万物者莫润乎水，终万物始万物者莫盛乎艮。故水火相逮，雷风不相悖，山泽通气，然后能变化，既成万物也。</p><p>乾，健也。坤，顺也。震，动也。巽，入也。坎，陷也。离，丽也。艮，止也。兑，说也。</p><p>乾为马，坤为牛，震为龙，巽为鸡，坎为豕，离为雉，艮为狗，兑为羊。</p><p>乾为首，坤为腹，震为足，巽为股，坎为耳，离为目，艮为手，兑为口。</p><p>乾，天也，故称乎父。坤，地也，故称乎母。震一索而得男，故谓之长男。</p><p>巽一索而得女，故谓之长女。坎再索而得男。故谓之中男。离谓之中男。离再索而得女，故谓之中女。艮三索而得男，故谓之少男。兑三索而得女，故谓之少女。</p><p>乾为天，为圆，为君，为父，为玉，为金，为寒，为冰，为大赤，为良马，为老马，为瘠马，为驳马，为木果。</p><p>坤为地，为母，为布，为釜，为吝啬，为均，为子母牛，为大舆，为文，为众，为柄，其于地也为黑。</p><p>震为雷，为龙，为玄黄，为旉，为大途，为长子，为决躁，为苍筤竹，为萑苇。其于马也，为善鸣，为馵足，为作足，为的颡。其于稼也，为反生。其究为健，为蕃鲜。</p><p>巽为木，为风，为长女，为绳直，为工，为白，为长，为高，为进退，为不果，为臭。其于人也，为寡发，为广颡，为多白眼，为近利市三倍，其究为躁卦。</p><p>坎为水，为沟渎，为隐伏，为矫輮，为弓轮。其于人也，为加忧，为心病，为耳痛，为血卦，为赤。其于马也，为美脊，为亟心，为下首，为薄蹄，为曳。</p><p>其于舆也，为多眚，为通，为月，为盗。其于木也，为坚多心。</p><p>离为火，为日，为电，为中女，为甲胄，为戈兵。其于人也，为大腹。为乾卦，为鳖，为蟹，为蠃，为蚌，为龟。其于木也，为科上槁。</p><p>艮为山，为径路，为小石，为门阙，为果蓏，为阍寺，为指，为狗，为鼠，为黔喙之属。其于木也，为坚多节。</p><p>兑为泽，为少女，为巫，为口舌，为毁折，为附决。其于地也，为刚卤。为妾，为羊。</p><p>主要记述并解说乾、坤、艮、兑、坎、离、震、巽八经卦所象征的各类事物，以及阐述六十四卦卦序排列原理和各卦的属性意义，以辅助占断吉凶。</p><p>八卦类象是将宇宙间万事万物分为八类，以八卦为标准进行划分。为了更好地理解和记忆八卦类象，可以采用以下方法：</p><ul><li>家庭角色法 ：将世界看做一个家庭，每个八卦代表不同的家庭成员或角色。例如，乾卦代表父亲（阳刚、权威），坤卦代表母亲（柔顺、包容），震卦代表长子（阳刚、有力），巽卦代表长女（柔顺、入内），坎卦代表中男（中坚力量、险难），离卦代表中女（光明、美丽），艮卦代表少男（静止、少动），兑卦代表少女（喜悦、说话）。</li></ul><p>家庭角色法 ：</p><ul><li><p>将世界看做一个家庭，每个八卦代表不同的家庭成员或角色。例如，乾卦代表父亲（阳刚、权威），坤卦代表母亲（柔顺、包容），震卦代表长子（阳刚、有力），巽卦代表长女（柔顺、入内），坎卦代表中男（中坚力量、险难），离卦代表中女（光明、美丽），艮卦代表少男（静止、少动），兑卦代表少女（喜悦、说话）。</p></li><li><p>三爻观察法 ：观察八卦中的三爻。当卦中三爻相同时，阳为男，阴为女；三爻不同时，数量最少的爻代表性别。例如，乾卦三个阳爻代表男性，坤卦三个阴爻代表女性；震卦一个阳爻在下代表长子，巽卦一个阴爻在下代表长女，以此类推。</p></li></ul><p>三爻观察法 ：</p><ul><li><p>观察八卦中的三爻。当卦中三爻相同时，阳为男，阴为女；三爻不同时，数量最少的爻代表性别。例如，乾卦三个阳爻代表男性，坤卦三个阴爻代表女性；震卦一个阳爻在下代表长子，巽卦一个阴爻在下代表长女，以此类推。</p></li><li><p>口诀记忆法 ：使用口诀帮助记忆八卦符号和类象。如“乾三连，坤六断，震仰盂，艮覆碗，离中虚，坎中满，兑上缺，巽下断”。这些口诀简洁明了，便于记忆八卦的基本形态和特征。</p></li></ul><p>口诀记忆法 ：</p><ul><li><p>使用口诀帮助记忆八卦符号和类象。如“乾三连，坤六断，震仰盂，艮覆碗，离中虚，坎中满，兑上缺，巽下断”。这些口诀简洁明了，便于记忆八卦的基本形态和特征。</p></li><li><p>联想记忆法 ：将八卦符号与具体事物进行联想，以增强记忆效果。例如，乾卦代表天，可以联想到广阔的蓝天和无限的可能；坤卦代表地，可以联想到肥沃的土地和孕育万物的母亲；震卦代表雷，可以联想到雷鸣电闪的震撼力量；等等。</p></li></ul><p>联想记忆法 ：</p><ul><li><p>将八卦符号与具体事物进行联想，以增强记忆效果。例如，乾卦代表天，可以联想到广阔的蓝天和无限的可能；坤卦代表地，可以联想到肥沃的土地和孕育万物的母亲；震卦代表雷，可以联想到雷鸣电闪的震撼力量；等等。</p></li><li><p>应用实践法 ：在实际应用中加深理解和记忆。通过占卜、风水、中医等领域的学习和实践，将八卦类象的知识与现实生活相结合，提高学习的趣味性和实用性。</p></li></ul><p>应用实践法 ：</p><ul><li>在实际应用中加深理解和记忆。通过占卜、风水、中医等领域的学习和实践，将八卦类象的知识与现实生活相结合，提高学习的趣味性和实用性。</li></ul>',37)])])}const h=l(t,[["render",s]]);export{d as __pageData,h as default};
